// src/types/operationSchema.ts
import type { BattleChapter, BattleReport } from './battleReport';
import type { EquipmentVariant } from '../graphics/equipmentTypes';

/**
 * 1. Attack Plan Schema (Generated by Mission Editor)
 */
export interface AttackPackageOrder {
  orderType: 'SALVO_STRIKE' | 'AIR_ASSAULT_INSERT' | 'GROUND_ADVANCE';
  sourceSlotId?: string;
  waypoints: string[];
  targetHexId: string;
  targetEntityIds?: string[];
  salvoAllocation?: Record<string, number>;
}

export interface AttackPackage {
  packageId: string;
  role: 'SUPPORT_SEAD' | 'PRIMARY_ASSAULT' | 'FEINT';
  phaseOffsetSec: number;
  primaryVariantId: string;
  attachedVariantIds?: string[];
  orders: AttackPackageOrder[];
}

export interface AttackPlanJson {
  schemaVersion: '1.0';
  operationId: string;
  attackerFactionId: string;
  environment: {
    timeOfDay: 'DAY' | 'DUSK' | 'NIGHT';
    weather: 'CLEAR' | 'OVERCAST' | 'RAIN';
  };
  variantsRegistry: Record<string, EquipmentVariant>;
  packages: AttackPackage[];
}

/**
 * 2. Defense State Schema (Theater Defender State)
 */
export interface DeployedDefenseEntity {
  entityId: string;
  displayName: string;
  variantId: string;
  hexId: string;
  networkId?: string;
  requiresNetworkRadar?: boolean;
  strengthPct: number;
  isHvt?: boolean;
}

export interface DefenseStateJson {
  schemaVersion: '1.0';
  defenderFactionId: string;
  variantsRegistry: Record<string, EquipmentVariant>;
  entities: DeployedDefenseEntity[];
}

/**
 * 3. Screenplay & Director Extensions
 */
export type CameraDirectorMode = 
  | 'SUB_CHASE' 
  | 'TRACK_ACTOR' 
  | 'MISSILE_CHASE' 
  | 'PAN_TO_TARGET' 
  | 'SKY_PULLAWAY' 
  | 'LANDING_LZ';

export interface DirectorDirective {
  mode: CameraDirectorMode;
  targetActorId?: string;
  cameraOffset?: [number, number, number];
  blendDurationSec?: number;
}

export interface ScriptCue {
  id: string;
  simClock: string;
  startSec: number;
  endSec: number;
  actorId: string;
  action: string;
  fromHex?: string;
  toHex?: string;
  headline: string;
  telemetryNote: string;
  director: DirectorDirective;
}

/**
 * 4. Battle Result Schema (Consumed by CinematicReplayManager)
 */
export type ReplayTimelineCommand =
  | {
      t: number;
      cmd: 'SPAWN';
      actorId: string;
      variantId: string;
      hexId: string;
      altitudeOffset?: number;
      count?: number;
    }
  | {
      t: number;
      cmd: 'MOVE_PATH';
      actorId: string;
      waypointHexIds: string[];
      durationSec: number;
      altitudeProfile: 'SUBSURFACE' | 'NAP_OF_THE_EARTH' | 'GROUND_CLAMP';
    }
  | {
      t: number;
      cmd: 'EMIT_PROJECTILE';
      sourceActorId: string;
      sourceSlotId: string;
      targetActorId: string;
      targetHexId: string;
      munitionVariantId: string;
      salvoCount: number;
      flightDurationSec: number;
      staggerSec: number;
    }
  | {
      t: number;
      cmd: 'DEPLOY_SUB_UNIT';
      parentActorId: string;
      sourceSlotId: string;
      childActorId: string;
      childVariantId: string;
      landingHexId: string;
    }
  | {
      t: number;
      cmd: 'IMPACT_STRIKE';
      targetActorId: string;
      hexId: string;
      newDamageState: 'INTACT' | 'SUPPRESSED' | 'DESTROYED';
    };

export interface BattleResultJson extends BattleReport {
  schemaVersion: '1.0';
  variantsRegistry: Record<string, EquipmentVariant>;
  timeline: ReplayTimelineCommand[];
  outcomes?: {
    seadSuccess: boolean;
    samInterceived: boolean;
    turnaroundTriggered: boolean;
  };
  scriptCues?: ScriptCue[];
}

